const body = $json.body ?? $json;
if (!/^\d{4}-\d{2}-\d{2}$/.test(body.targetWeekStart ?? '')) throw new Error('targetWeekStart must be YYYY-MM-DD');
const state = $getWorkflowStaticData('global');
state.contexts = state.contexts ?? {};
state.contexts[body.targetWeekStart] = {...body, publishedAt: new Date().toISOString()};
const keys = Object.keys(state.contexts).sort().reverse();
for (const key of keys.slice(8)) delete state.contexts[key];
return [{json:{ok:true,targetWeekStart:body.targetWeekStart}}];

const start = $json.query?.targetWeekStart ?? '';
const state = $getWorkflowStaticData('global');
const context = state.contexts?.[start];
return [{json:context ? {found:true,context} : {found:false,targetWeekStart:start,message:'No coaching context has been published for this week.'}}];

const report = $json.body ?? $json;
const required = ['id','targetWeekStart','createdAt','coachName','trainingSummary','weeklyFocus','runDistanceMultiplier','cycleDistanceMultiplier','scheduleObservations','targetFeedback','availabilityTip'];
for (const key of required) if (report[key] === undefined || report[key] === null || report[key] === '') throw new Error(`Missing ${key}`);
if (!/^\d{4}-\d{2}-\d{2}$/.test(report.targetWeekStart)) throw new Error('targetWeekStart must be YYYY-MM-DD');
for (const key of ['runDistanceMultiplier','cycleDistanceMultiplier']) if (typeof report[key] !== 'number' || report[key] < 0.8 || report[key] > 1.1) throw new Error(`${key} must be between 0.8 and 1.1`);
if (!Array.isArray(report.scheduleObservations) || report.scheduleObservations.length > 6) throw new Error('scheduleObservations is invalid');
if (!Array.isArray(report.targetFeedback) || report.targetFeedback.length > 6) throw new Error('targetFeedback is invalid');
const state = $getWorkflowStaticData('global');
state.reports = state.reports ?? {};
state.reports[report.targetWeekStart] = report;
const keys = Object.keys(state.reports).sort().reverse();
for (const key of keys.slice(8)) delete state.reports[key];
return [{json:{ok:true,targetWeekStart:report.targetWeekStart}}];

const start = $json.query?.targetWeekStart ?? '';
const state = $getWorkflowStaticData('global');
const report = state.reports?.[start];
return [{json:report ? {found:true,report} : {found:false,targetWeekStart:start,message:'No coaching report has been submitted for this week.'}}];
